const input = $input.first().json;

function parseNumber(value, fieldName, fallback = null) {
  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    if (fallback !== null) {
      return fallback;
    }

    throw new Error(
      fieldName + ' is required.'
    );
  }

  const cleaned = String(value)
    .split(',')
    .join('')
    .split('$')
    .join('')
    .split('%')
    .join('')
    .trim();

  const parsed = Number(cleaned);

  if (!Number.isFinite(parsed)) {
    throw new Error(
      fieldName + ' must be numeric.'
    );
  }

  return parsed;
}

function parseRate(value, fieldName, fallback) {
  const parsed = parseNumber(
    value,
    fieldName,
    fallback
  );

  return Math.abs(parsed) > 1
    ? parsed / 100
    : parsed;
}

function roundMoney(value) {
  return Math.round(
    (value + Number.EPSILON) * 100
  ) / 100;
}

const currentAge = parseNumber(
  input.current_age,
  'current_age'
);

const retirementAge = parseNumber(
  input.retirement_age,
  'retirement_age'
);

const currentPortfolio = parseNumber(
  input.current_portfolio_value,
  'current_portfolio_value',
  0
);

const monthlyContribution = parseNumber(
  input.monthly_contribution,
  'monthly_contribution',
  0
);

const desiredMonthlyIncome = parseNumber(
  input.desired_monthly_income_today,
  'desired_monthly_income_today'
);

const otherMonthlyIncome = parseNumber(
  input.other_monthly_income_today,
  'other_monthly_income_today',
  0
);

const inflationRate = parseRate(
  input.inflation_rate_percent,
  'inflation_rate_percent',
  2.5
);

const withdrawalRate = parseRate(
  input.withdrawal_rate_percent,
  'withdrawal_rate_percent',
  4
);

const conservativeReturn = parseRate(
  input.conservative_return_percent,
  'conservative_return_percent',
  4
);

const baseReturn = parseRate(
  input.base_return_percent,
  'base_return_percent',
  6
);

const optimisticReturn = parseRate(
  input.optimistic_return_percent,
  'optimistic_return_percent',
  8
);

const yearsToGoal =
  retirementAge - currentAge;

if (yearsToGoal <= 0) {
  throw new Error(
    'retirement_age must be greater than current_age.'
  );
}

if (withdrawalRate <= 0) {
  throw new Error(
    'withdrawal_rate_percent must be greater than zero.'
  );
}

const monthsToGoal =
  Math.round(yearsToGoal * 12);

const monthlyIncomeGapToday =
  Math.max(
    desiredMonthlyIncome -
    otherMonthlyIncome,
    0
  );

const monthlyIncomeGapAtRetirement =
  monthlyIncomeGapToday *
  Math.pow(
    1 + inflationRate,
    yearsToGoal
  );

const annualIncomeNeededAtRetirement =
  monthlyIncomeGapAtRetirement * 12;

const targetCorpus =
  annualIncomeNeededAtRetirement /
  withdrawalRate;

function calculateScenario(
  scenarioName,
  annualReturn
) {
  const monthlyReturn =
    annualReturn / 12;

  const growthFactor =
    Math.pow(
      1 + monthlyReturn,
      monthsToGoal
    );

  const futureValueCurrentPortfolio =
    currentPortfolio * growthFactor;

  const futureValueContributions =
    monthlyReturn === 0
      ? monthlyContribution * monthsToGoal
      : monthlyContribution *
        (
          (growthFactor - 1) /
          monthlyReturn
        );

  const projectedCorpus =
    futureValueCurrentPortfolio +
    futureValueContributions;

  const fundingGap =
    targetCorpus - projectedCorpus;

  let requiredMonthlyContribution = 0;

  if (
    targetCorpus >
    futureValueCurrentPortfolio
  ) {
    requiredMonthlyContribution =
      monthlyReturn === 0
        ? (
            targetCorpus -
            futureValueCurrentPortfolio
          ) / monthsToGoal
        : (
            targetCorpus -
            futureValueCurrentPortfolio
          ) *
          monthlyReturn /
          (growthFactor - 1);
  }

  return {
    scenario: scenarioName,

    annual_return_percent:
      annualReturn * 100,

    projected_corpus:
      roundMoney(projectedCorpus),

    funding_gap:
      roundMoney(fundingGap),

    required_monthly_contribution:
      roundMoney(
        Math.max(
          requiredMonthlyContribution,
          0
        )
      ),

    funded_percentage:
      roundMoney(
        targetCorpus === 0
          ? 100
          : projectedCorpus /
            targetCorpus *
            100
      ),

    feasible:
      projectedCorpus >= targetCorpus
  };
}

const scenarios = [
  calculateScenario(
    'conservative',
    conservativeReturn
  ),

  calculateScenario(
    'base',
    baseReturn
  ),

  calculateScenario(
    'optimistic',
    optimisticReturn
  )
];

const baseScenario =
  scenarios.find(
    scenario =>
      scenario.scenario === 'base'
  );

return [
  {
    json: {
      answer_type:
        'retirement_feasibility',

      years_to_goal:
        yearsToGoal,

      desired_monthly_income_today:
        roundMoney(
          desiredMonthlyIncome
        ),

      monthly_income_needed_at_retirement:
        roundMoney(
          monthlyIncomeGapAtRetirement
        ),

      annual_income_needed_at_retirement:
        roundMoney(
          annualIncomeNeededAtRetirement
        ),

      target_retirement_corpus:
        roundMoney(targetCorpus),

      current_portfolio_value:
        roundMoney(currentPortfolio),

      current_monthly_contribution:
        roundMoney(monthlyContribution),

      base_projected_corpus:
        baseScenario.projected_corpus,

      base_funding_gap:
        baseScenario.funding_gap,

      base_required_monthly_contribution:
        baseScenario
          .required_monthly_contribution,

      feasible_under_base_assumptions:
        baseScenario.feasible,

      scenarios,

      assumptions: {
        inflation_rate_percent:
          inflationRate * 100,

        withdrawal_rate_percent:
          withdrawalRate * 100,

        contribution_timing:
          'end of each month',

        taxes_included:
          false,

        social_security_included:
          otherMonthlyIncome > 0
      },

      educational_notice:
        'This is an educational projection based on the supplied assumptions, not a guaranteed financial outcome.'
    }
  }
];
